def p(text):
    return '<p>' + text + '</p>'


def bullets(*items):
    return '<ul>' + ''.join('<li>' + text + '</li>' for text in items) + '</ul>'


def table(headers, rows):
    return '<div class="reading-table"><table><thead><tr>' + ''.join('<th scope="col">' + text + '</th>' for text in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(text) + '</td>' for text in row) + '</tr>' for row in rows) + '</tbody></table></div>'


